        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .connecting(transport: try FfiConverterTypeTransport.read(from: &buf)
        )
        
        case 2: return .connected(transport: try FfiConverterTypeTransport.read(from: &buf), path: try FfiConverterTypeLinkPath.read(from: &buf)
        )
        
        case 3: return .pathChanged(path: try FfiConverterTypeLinkPath.read(from: &buf)
        )
        
        case 4: return .rtt(millis: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 5: return .media(state: try FfiConverterTypeMediaState.read(from: &buf)
        )
        
        case 6: return .disconnected(reason: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .suspect(silentMillis: try FfiConverterUInt32.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LinkEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .connecting(transport):
            writeInt(&buf, Int32(1))
            FfiConverterTypeTransport.write(transport, into: &buf)
            
        
        case let .connected(transport,path):
            writeInt(&buf, Int32(2))
            FfiConverterTypeTransport.write(transport, into: &buf)
            FfiConverterTypeLinkPath.write(path, into: &buf)
            
        
        case let .pathChanged(path):
            writeInt(&buf, Int32(3))
            FfiConverterTypeLinkPath.write(path, into: &buf)
            
        
        case let .rtt(millis):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(millis, into: &buf)
            
        
        case let .media(state):
            writeInt(&buf, Int32(5))
            FfiConverterTypeMediaState.write(state, into: &buf)
            
        
        case let .disconnected(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .suspect(silentMillis):
            writeInt(&buf, Int32(7))
            FfiConverterUInt32.write(silentMillis, into: &buf)
            
        }
    }
}


